// Generated by scripts/build_drilling_rop.py; edit drilling-rop-case/ instead.
(function (global) {
  'use strict';
  var pack = {"manifest":{"id":"drilling-rop","sceneId":"d1","methods":["opt"],"title":"钻速预测与参数优化：回归代理与约束搜索","version":"1.0.0","updated":"2026-10-23","tabs":{"background":{"label":"专业背景","lede":"钻压、转速、循环流量与岩层共同影响机械钻速。用可复现的合成数据学习响应，再在限定范围内比较参数，理解预测、优化与工程安全之间的边界。","judge":[{"label":"数据形态","value":"多变量记录","desc":"参数、岩层与机械钻速，按井分组"},{"label":"模型方法","value":"回归 + 寻优","desc":"标准化多项式岭回归与网格搜索"},{"label":"可见收益","value":"批量比较","desc":"用响应面比较 1,271 组候选参数"},{"label":"落地难度","value":"高","desc":"跨井泛化与真实作业约束待验证"}],"sections":[{"no":1,"en":"PROBLEM","title":"钻速影响因素","html":"<p>机械钻速 ROP 是钻头破岩、使井眼加深的速度，本例用 m/h 表示。钻压 WOB 是施加在钻头上的轴向力，用 kN 表示；转速 RPM 用 r/min 表示；流量 Q 是单位时间循环的钻井液体积，用 L/s 表示。流量参与井底清洁和岩屑输送，不能把它当作泵压。岩层的强度与可钻性改变破岩响应，因此相同的钻压、转速和流量不保证得到相同钻速。</p><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 416\" width=\"100%\" role=\"img\" aria-label=\"钻头、岩层与钻压、转速、流量、机械钻速的关系示意\" style=\"display:block;max-width:100%;height:auto;background:#f8fafc;border-radius:12px\"><title>钻头、岩层与钻压、转速、流量、机械钻速的关系示意</title><g font-family=\"system-ui,sans-serif\" font-size=\"16\" fill=\"#1e293b\">\n<rect x=\"24\" y=\"104\" width=\"752\" height=\"85\" rx=\"8\" fill=\"#fef3c7\"/>\n<rect x=\"24\" y=\"189\" width=\"752\" height=\"85\" fill=\"#e2e8f0\"/>\n<rect x=\"24\" y=\"274\" width=\"752\" height=\"80\" rx=\"8\" fill=\"#ffedd5\"/>\n<text x=\"46\" y=\"147\">砂岩（示意）</text><text x=\"46\" y=\"232\">页岩（示意）</text><text x=\"46\" y=\"316\">致密灰岩（示意）</text>\n<rect x=\"288\" y=\"104\" width=\"182\" height=\"176\" fill=\"#fff\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n<rect x=\"349\" y=\"90\" width=\"60\" height=\"156\" rx=\"8\" fill=\"#cbd5e1\" stroke=\"#64748b\" stroke-width=\"2\"/>\n<path d=\"M334 246 H424 L413 277 H345 Z\" fill=\"#64748b\"/><circle cx=\"351\" cy=\"270\" r=\"9\" fill=\"#94a3b8\"/><circle cx=\"379\" cy=\"275\" r=\"9\" fill=\"#94a3b8\"/><circle cx=\"407\" cy=\"270\" r=\"9\" fill=\"#94a3b8\"/>\n<text x=\"40\" y=\"36\" font-weight=\"700\">机械输入 + 循环携岩 + 岩层条件 → 机械钻速</text>\n<path d=\"M379 48 V82 M372 72 L379 82 L386 72\" fill=\"none\" stroke=\"#b45309\" stroke-width=\"3\"/><text x=\"436\" y=\"69\">WOB 钻压 / kN：向钻头施力</text>\n<path d=\"M314 105 C279 65 459 65 438 105 M429 97 L438 105 L447 97\" fill=\"none\" stroke=\"#7c3aed\" stroke-width=\"3\"/><text x=\"503\" y=\"111\">RPM / r/min：旋转破岩</text>\n<path d=\"M379 118 V224 M372 214 L379 224 L386 214 M322 234 V139 M315 149 L322 139 L329 149\" fill=\"none\" stroke=\"#0284c7\" stroke-width=\"3\"/>\n<text x=\"499\" y=\"183\">Q 流量 / L/s</text><text x=\"499\" y=\"209\">钻柱内下行、环空返出携岩</text>\n<path d=\"M453 286 V327 M446 317 L453 327 L460 317\" fill=\"none\" stroke=\"#0f766e\" stroke-width=\"3\"/>\n<text x=\"499\" y=\"300\">ROP / m/h：井眼加深速度</text><text x=\"499\" y=\"326\">同一参数在不同岩层响应不同</text>\n<text x=\"40\" y=\"390\" font-size=\"14\" fill=\"#475569\">概念示意，不表示尺寸比例、真实分层或通用最优参数；流量不等于泵压。</text>\n</g></svg><p>现场调整通常综合作业设计、邻井资料和实时工况。数据模型可以帮助比较参数组合，但提高输入并不保证钻速持续上升。这里的岩层名称只用于分类编码，不宣称“某岩性一定更快”。术语依据：<a href=\"https://glossary.slb.com/terms/r/rate_of_penetration\" target=\"_blank\" rel=\"noopener noreferrer\">SLB：ROP</a>、<a href=\"https://glossary.slb.com/terms/d/drill_collar\" target=\"_blank\" rel=\"noopener noreferrer\">钻压与钻铤</a>、<a href=\"https://glossary.slb.com/terms/h/hole_cleaning\" target=\"_blank\" rel=\"noopener noreferrer\">携岩</a>。</p>"},{"no":2,"en":"INTERVENTION","title":"钻速回归与参数优化","html":"<p>本例把多变量回归作为代理模型：由 WOB、RPM、Q 与岩层估计 ROP。连续参数按固定尺度变换后构造多项式非线性与交互项，岩层用以砂岩为参照的 one-hot 编码并加入岩层与参数交互；全部特征仅用训练集统计量标准化，再用岭回归控制系数规模。随后固定流量和岩层，在钻压上限、转速上限及演示采样范围内网格搜索，推荐模型预测钻速最高的候选点。这是静态监督回归与离散寻优演示，不使用深度网络或强化学习，也不预测未来完整时序。</p><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 348\" width=\"100%\" role=\"img\" aria-label=\"合成数据经回归模型进入约束网格搜索，测试集用于独立评价\" style=\"display:block;max-width:100%;height:auto;background:#f8fafc;border-radius:12px\"><title>合成数据经回归模型进入约束网格搜索，测试集用于独立评价</title><g font-family=\"system-ui,sans-serif\" font-size=\"16\" fill=\"#1e293b\">\n<text x=\"28\" y=\"34\" font-weight=\"700\">先学习响应，再在限定范围内比较候选参数</text>\n<rect x=\"24\" y=\"65\" width=\"222\" height=\"130\" rx=\"10\" fill=\"#e0f2fe\"/>\n<text x=\"42\" y=\"94\" font-weight=\"700\">固定种子合成数据</text><text x=\"42\" y=\"124\">WOB / RPM / Q / 岩层</text><text x=\"42\" y=\"150\">目标：合成 ROP</text><text x=\"42\" y=\"176\">按虚拟井分组</text>\n<path d=\"M252 127 H279 L270 120 M279 127 L270 134\" stroke=\"#64748b\" stroke-width=\"2\" fill=\"none\"/>\n<rect x=\"286\" y=\"65\" width=\"228\" height=\"130\" rx=\"10\" fill=\"#ede9fe\"/>\n<text x=\"304\" y=\"94\" font-weight=\"700\">标准化多项式岭回归</text><text x=\"304\" y=\"124\">非线性项 + 参数交互</text><text x=\"304\" y=\"150\">岩层 one-hot</text><text x=\"304\" y=\"176\">输出：预测 ROP</text>\n<path d=\"M520 127 H547 L538 120 M547 127 L538 134\" stroke=\"#64748b\" stroke-width=\"2\" fill=\"none\"/>\n<rect x=\"554\" y=\"65\" width=\"222\" height=\"130\" rx=\"10\" fill=\"#ccfbf1\"/>\n<text x=\"572\" y=\"94\" font-weight=\"700\">约束内网格搜索</text><text x=\"572\" y=\"124\">固定 Q 与岩层</text><text x=\"572\" y=\"150\">限制 WOB / RPM 上限</text><text x=\"572\" y=\"176\">取网格内预测最大值</text>\n<rect x=\"24\" y=\"222\" width=\"490\" height=\"69\" rx=\"10\" fill=\"#f1f5f9\" stroke=\"#cbd5e1\"/>\n<text x=\"42\" y=\"250\">测试井 → 预测与合成观测散点 → MAE / R²</text><text x=\"42\" y=\"275\" font-size=\"14\">评价集不参与拟合、标准化或调参</text>\n<rect x=\"554\" y=\"222\" width=\"222\" height=\"69\" rx=\"10\" fill=\"#fef3c7\"/>\n<text x=\"572\" y=\"250\">推荐只更新演示输入</text><text x=\"572\" y=\"275\" font-size=\"14\">预测增量 ≠ 现场实测收益</text>\n<text x=\"28\" y=\"325\" font-size=\"14\" fill=\"#475569\">矩形范围只表达教学约束，不包含扭矩、泵压、振动、井控与井壁稳定判定。</text>\n</g></svg><p>热力图展示的是模型预测响应面；当前与推荐的钻速对比必须由同一模型、同一流量与岩层计算。界面中的增量是预测差值，不是现场实测提速。原始研究证明了机器学习建模这一研究方向，但没有验证本例模型：<a href=\"https://link.springer.com/article/10.1007/s13202-020-01066-1\" target=\"_blank\" rel=\"noopener noreferrer\">Brenjkar 等，2021，原文</a>。</p><p>合成观测与预测统一设 0.5 m/h 的教学下限，用于避免出现负钻速；这不是现场停钻阈值。参考方向：非线性回归、代理模型、约束优化。</p>"},{"no":3,"en":"DATA","title":"数据准备与样本划分","html":"<p>演示在浏览器中以固定种子生成多口虚拟井，每条记录包含井标识、WOB（kN）、RPM（r/min）、Q（L/s）、岩层类别及合成观测 ROP（m/h）。岩层采用砂岩、页岩、致密灰岩，其响应排序仅为教学设定。合成关系包含非线性、交互、井间差异与噪声；它只是教学假设，不是经过标定的破岩定律。井标识用于分组切分，不作为可记忆井号的预测输入。</p><p>先按虚拟井划分训练、验证、测试集，同一井不能跨集合；训练集拟合标准化统计量和回归系数，验证集选择正则强度，测试井仅作最终评价。这样减少同井相似样本混入两端带来的乐观偏差。未来使用真实资料，还需核对时间或深度对齐、钻进工况、传感器量纲、岩性解释在预测时是否可获得，以及钻头与钻井液等遗漏因素。方法依据：<a href=\"https://scikit-learn.org/stable/modules/generated/sklearn.model_selection.GroupShuffleSplit.html\" target=\"_blank\" rel=\"noopener noreferrer\">按组切分</a>、<a href=\"https://scikit-learn.org/stable/common_pitfalls.html\" target=\"_blank\" rel=\"noopener noreferrer\">数据泄漏防范</a>。</p>"},{"no":4,"en":"LIMITS","title":"模型适用范围与工程约束","html":"<p>钻压与转速过高可能加剧钻头磨损、井眼清洁问题与钻柱不稳定，关系也随地层和工具变化。只最大化 ROP 无法替代扭矩、泵压、振动、井控、井壁稳定和设备能力检查。工程使用需依据具体井段设计及设备资料建立约束并经专业人员审核；本例不提供通用工程阈值。依据：<a href=\"https://link.springer.com/article/10.1007/s13202-020-01066-1\" target=\"_blank\" rel=\"noopener noreferrer\">原文引言中的非线性与作业风险讨论</a>。</p><p>演示中的上限是用户调整的教学搜索边界，不是安全认证；网格最优只针对当前模型和离散候选点。“应用推荐”只把推荐 WOB/RPM 写回浏览器演示控件，不控制钻机。独立测试井仍来自同一个合成生成器；即使 MAE 很小、R² 很高，也不能证明真实井泛化能力、安全性或工程提效，不预填任何真实提升比例。</p>"}]},"workflow":{"label":"案例流程","title":"钻速建模与参数优化流程","lead":["浏览器完成数据生成、按井切分、回归拟合、独立测试和预测网格搜索。数值结果由演示运行时计算，不预填工程效果。"],"stats":[["数据来源","固定种子合成"],["切分单位","虚拟井"],["推荐范围","教学约束内"]],"steps":[{"name":"合成数据生成与井组划分","role":"数据","do":"固定种子生成多口虚拟井的钻压、转速、流量、岩层与合成观测钻速；按井标识分训练、验证、测试集。","effect":"获得可复现且井标识互不交叉的三个集合，界面展示各集合规模。","trap":"不能把同井相邻记录逐行打散到训练与测试；合成井不代表真实井的变化。"},{"name":"特征构造与回归训练","role":"模型","do":"先按固定尺度构造 WOB、RPM、Q 的一次、平方及交互项，加入岩层 one-hot 和岩层与参数交互；仅用训练集统计量标准化特征并拟合岭回归。","effect":"得到由参数与岩层到预测 ROP 的映射，单位为 m/h。","trap":"验证与测试数据只能复用训练得到的变换；未见岩层与超范围输入不能假装可靠。"},{"name":"模型选择与独立测试","role":"评价","do":"以验证井 MAE 选择正则强度，保留所选训练模型且不重新拟合；在独立测试井计算 MAE 与 R²，绘制合成观测对预测的散点图。","effect":"检查未参与训练的合成井上误差大小，以及预测偏差和离群点。","trap":"不能依据测试误差继续调参；测试集同源于合成生成器，不是现场验证。"},{"name":"约束参数网格搜索","role":"优化","do":"选择流量和岩层，调整钻压与转速上限；在演示采样范围和上限的交集内，逐点用冻结模型预测 WOB/RPM 网格。","effect":"热力图显示预测响应面，并标出当前点与网格内推荐点。","trap":"操作上限只在样本范围内变化，界面始终保留至少一个候选点；不能把这两个上限当作完整安全校核。"},{"name":"推荐参数对比与应用","role":"交互","do":"在相同流量、岩层与模型下比较当前和推荐预测 ROP；点击应用推荐，将 WOB/RPM 更新到演示控件。","effect":"观察推荐参数、预测差值与热力图位置之间的对应关系。","trap":"预测增量不等于实测收益；点击仅改变页面状态，不代表工程执行或安全许可。"}],"metrics":{"title":"模型误差与参数约束评价","html":"<div style=\"display:flex;flex-wrap:wrap;gap:16px;margin:16px 0\"><figure style=\"flex:1 1 220px;margin:0;padding:16px;background:#f5f6f2;border-radius:6px\"><b>1. 数据：按井分开</b><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 220 120\" width=\"220\" role=\"img\" aria-label=\"1. 数据：按井分开\" style=\"display:block;width:100%;max-width:260px;height:auto;margin:12px auto\"><g font-family=\"system-ui,sans-serif\" font-size=\"13\" fill=\"#4d565b\"><rect x=\"10\" y=\"30\" width=\"133\" height=\"30\" fill=\"#2f7d6b\"/><rect x=\"146\" y=\"30\" width=\"32\" height=\"30\" fill=\"#41699b\"/><rect x=\"181\" y=\"30\" width=\"32\" height=\"30\" fill=\"#b26a39\"/><text x=\"10\" y=\"22\">18 口虚拟井 / 1,080 条记录</text><text x=\"10\" y=\"86\">训练 12 井 · 验证 3 井 · 测试 3 井</text></g></svg><figcaption style=\"font-size:13px;color:#4d565b;line-height:1.7\">同井样本留在同一集合。训练学规律、验证选模型、测试检查未见井误差。</figcaption></figure><figure style=\"flex:1 1 220px;margin:0;padding:16px;background:#f5f6f2;border-radius:6px\"><b>2. 模型：学习弯曲响应</b><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 220 120\" width=\"220\" role=\"img\" aria-label=\"2. 模型：学习弯曲响应\" style=\"display:block;width:100%;max-width:260px;height:auto;margin:12px auto\"><g font-family=\"system-ui,sans-serif\" font-size=\"13\" fill=\"#4d565b\"><path d=\"M25 10V95H210\" fill=\"none\" stroke=\"#9ba3a9\"/><path d=\"M30 87Q125-25 205 42\" fill=\"none\" stroke=\"#2f7d6b\" stroke-width=\"3\"/><g fill=\"#41699b\"><circle cx=\"45\" cy=\"72\" r=\"4\"/><circle cx=\"75\" cy=\"48\" r=\"4\"/><circle cx=\"105\" cy=\"28\" r=\"4\"/><circle cx=\"135\" cy=\"23\" r=\"4\"/><circle cx=\"165\" cy=\"22\" r=\"4\"/><circle cx=\"192\" cy=\"36\" r=\"4\"/></g><text x=\"30\" y=\"117\">参数 → 非线性特征 → 预测钻速</text></g></svg><figcaption style=\"font-size:13px;color:#4d565b;line-height:1.7\">平方项与交互项让回归描述非线性；标准化参数只从训练井估计。曲线是机制示意。</figcaption></figure><figure style=\"flex:1 1 220px;margin:0;padding:16px;background:#f5f6f2;border-radius:6px\"><b>3. 评价：预测对照观测</b><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 220 120\" width=\"220\" role=\"img\" aria-label=\"3. 评价：预测对照观测\" style=\"display:block;width:100%;max-width:260px;height:auto;margin:12px auto\"><g font-family=\"system-ui,sans-serif\" font-size=\"13\" fill=\"#4d565b\"><path d=\"M25 10V95H210\" fill=\"none\" stroke=\"#9ba3a9\"/><path d=\"M30 90L200 15\" fill=\"none\" stroke=\"#9ba3a9\" stroke-dasharray=\"4 3\"/><g fill=\"#2f7d6b\"><circle cx=\"45\" cy=\"80\" r=\"4\"/><circle cx=\"65\" cy=\"78\" r=\"4\"/><circle cx=\"90\" cy=\"60\" r=\"4\"/><circle cx=\"115\" cy=\"49\" r=\"4\"/><circle cx=\"140\" cy=\"49\" r=\"4\"/><circle cx=\"170\" cy=\"24\" r=\"4\"/><circle cx=\"193\" cy=\"26\" r=\"4\"/></g><text x=\"30\" y=\"117\">越靠近对角线，误差越小</text></g></svg><figcaption style=\"font-size:13px;color:#4d565b;line-height:1.7\">验证集从 5 个 λ 中选型；冻结模型后，用测试井计算 MAE、R² 并与均值基线比较。</figcaption></figure><figure style=\"flex:1 1 220px;margin:0;padding:16px;background:#f5f6f2;border-radius:6px\"><b>4. 寻优：筛掉越界组合</b><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 220 120\" width=\"220\" role=\"img\" aria-label=\"4. 寻优：筛掉越界组合\" style=\"display:block;width:100%;max-width:260px;height:auto;margin:12px auto\"><g font-family=\"system-ui,sans-serif\" font-size=\"13\" fill=\"#4d565b\"><rect x=\"15\" y=\"8\" width=\"23\" height=\"16\" fill=\"#e1e6e4\"/><rect x=\"39\" y=\"8\" width=\"23\" height=\"16\" fill=\"#e1e6e4\"/><rect x=\"63\" y=\"8\" width=\"23\" height=\"16\" fill=\"#e1e6e4\"/><rect x=\"87\" y=\"8\" width=\"23\" height=\"16\" fill=\"#e1e6e4\"/><rect x=\"111\" y=\"8\" width=\"23\" height=\"16\" fill=\"#e1e6e4\"/><rect x=\"135\" y=\"8\" width=\"23\" height=\"16\" fill=\"#e1e6e4\"/><rect x=\"159\" y=\"8\" width=\"23\" height=\"16\" fill=\"#e1e6e4\"/><rect x=\"183\" y=\"8\" width=\"23\" height=\"16\" fill=\"#e1e6e4\"/><rect x=\"15\" y=\"25\" width=\"23\" height=\"16\" fill=\"#bdd9cf\"/><rect x=\"39\" y=\"25\" width=\"23\" height=\"16\" fill=\"#7eb4a4\"/><rect x=\"63\" y=\"25\" width=\"23\" height=\"16\" fill=\"#7eb4a4\"/><rect x=\"87\" y=\"25\" width=\"23\" height=\"16\" fill=\"#2f7d6b\"/><rect x=\"111\" y=\"25\" width=\"23\" height=\"16\" fill=\"#2f7d6b\"/><rect x=\"135\" y=\"25\" width=\"23\" height=\"16\" fill=\"#2f7d6b\"/><rect x=\"159\" y=\"25\" width=\"23\" height=\"16\" fill=\"#e1e6e4\"/><rect x=\"183\" y=\"25\" width=\"23\" height=\"16\" fill=\"#e1e6e4\"/><rect x=\"15\" y=\"42\" width=\"23\" height=\"16\" fill=\"#bdd9cf\"/><rect x=\"39\" y=\"42\" width=\"23\" height=\"16\" fill=\"#bdd9cf\"/><rect x=\"63\" y=\"42\" width=\"23\" height=\"16\" fill=\"#7eb4a4\"/><rect x=\"87\" y=\"42\" width=\"23\" height=\"16\" fill=\"#7eb4a4\"/><rect x=\"111\" y=\"42\" width=\"23\" height=\"16\" fill=\"#2f7d6b\"/><rect x=\"135\" y=\"42\" width=\"23\" height=\"16\" fill=\"#2f7d6b\"/><rect x=\"159\" y=\"42\" width=\"23\" height=\"16\" fill=\"#e1e6e4\"/><rect x=\"183\" y=\"42\" width=\"23\" height=\"16\" fill=\"#e1e6e4\"/><rect x=\"15\" y=\"59\" width=\"23\" height=\"16\" fill=\"#e6f1ec\"/><rect x=\"39\" y=\"59\" width=\"23\" height=\"16\" fill=\"#bdd9cf\"/><rect x=\"63\" y=\"59\" width=\"23\" height=\"16\" fill=\"#bdd9cf\"/><rect x=\"87\" y=\"59\" width=\"23\" height=\"16\" fill=\"#7eb4a4\"/><rect x=\"111\" y=\"59\" width=\"23\" height=\"16\" fill=\"#7eb4a4\"/><rect x=\"135\" y=\"59\" width=\"23\" height=\"16\" fill=\"#2f7d6b\"/><rect x=\"159\" y=\"59\" width=\"23\" height=\"16\" fill=\"#e1e6e4\"/><rect x=\"183\" y=\"59\" width=\"23\" height=\"16\" fill=\"#e1e6e4\"/><rect x=\"15\" y=\"76\" width=\"23\" height=\"16\" fill=\"#e6f1ec\"/><rect x=\"39\" y=\"76\" width=\"23\" height=\"16\" fill=\"#e6f1ec\"/><rect x=\"63\" y=\"76\" width=\"23\" height=\"16\" fill=\"#bdd9cf\"/><rect x=\"87\" y=\"76\" width=\"23\" height=\"16\" fill=\"#bdd9cf\"/><rect x=\"111\" y=\"76\" width=\"23\" height=\"16\" fill=\"#7eb4a4\"/><rect x=\"135\" y=\"76\" width=\"23\" height=\"16\" fill=\"#7eb4a4\"/><rect x=\"159\" y=\"76\" width=\"23\" height=\"16\" fill=\"#e1e6e4\"/><rect x=\"183\" y=\"76\" width=\"23\" height=\"16\" fill=\"#e1e6e4\"/><circle cx=\"75\" cy=\"67\" r=\"5\" fill=\"white\" stroke=\"#242b2e\" stroke-width=\"2\"/><path d=\"M147 27l6 6-6 6-6-6z\" fill=\"#41699b\"/><text x=\"15\" y=\"117\">圆：当前　菱形：推荐　灰：越界</text></g></svg><figcaption style=\"font-size:13px;color:#4d565b;line-height:1.7\">固定岩层与排量，比较 1,271 组钻压 / 转速。只从满足上限的点中选预测最高者。</figcaption></figure><figure style=\"flex:1 1 220px;margin:0;padding:16px;background:#f5f6f2;border-radius:6px\"><b>5. 应用：比较同一模型</b><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 220 120\" width=\"220\" role=\"img\" aria-label=\"5. 应用：比较同一模型\" style=\"display:block;width:100%;max-width:260px;height:auto;margin:12px auto\"><g font-family=\"system-ui,sans-serif\" font-size=\"13\" fill=\"#4d565b\"><text x=\"10\" y=\"25\">当前</text><rect x=\"55\" y=\"10\" width=\"85\" height=\"23\" fill=\"#9ba3a9\"/><text x=\"10\" y=\"65\">推荐</text><rect x=\"55\" y=\"50\" width=\"140\" height=\"23\" fill=\"#2f7d6b\"/><text x=\"10\" y=\"108\">预测对比示意 · 运行值由模型计算</text></g></svg><figcaption style=\"font-size:13px;color:#4d565b;line-height:1.7\">应用推荐会更新当前参数，预测差值随之归零。收紧上限可能使推荐值低于越界的当前值。</figcaption></figure></div><p><b>评价对象</b>：测试井的合成观测 ROP 与模型预测 ROP。散点图横轴为合成观测值、纵轴为预测值，均为 m/h；y = x 是理想一致线，偏离表示误差，不是参数寻优曲线。</p><p><b>MAE</b> = Σ|预测值 − 合成观测值| / n，单位 m/h，越小表示本测试集平均绝对误差越小。<b>R²</b> = 1 − Σ(观测值 − 预测值)² / Σ(观测值 − 测试均值)²，无量纲，可能为负；观测值无方差时应显示不可定义，不能伪报满分。展示实际运行结果，不设置无来源的“工程达标线”。</p><p><b>推荐对比</b>：Δ预测 ROP = 推荐点预测值 − 当前点预测值；若展示相对增量，必须说明以当前预测值为分母，且分母须大于零。推荐需满足当前 WOB/RPM 上限和演示采样范围；当前点若越界应明确标识。热力图颜色表示预测钻速，不能表示安全等级。</p><p><b>切分边界</b>：训练井确定变换和系数，验证井选择模型，测试井只计算最终指标。井数、样本数、种子与切分应可核对；所有结果仅衡量同源合成数据上的拟合与泛化，无法验证真实工程效果。</p>"},"fails":[{"name":"同井数据泄漏","why":"把同井相关记录分散到多个集合，模型可能利用相似背景得到过于乐观的测试结果。"},{"name":"模型外推与遗漏变量","why":"超出样本覆盖或更换工具、岩层后预测可能失真；当前模型未显式描述扭矩、磨损、压力和振动。"},{"name":"工程约束缺失","why":"仅限制 WOB/RPM 不能证明井控、携岩或井壁稳定满足要求。"},{"name":"合成评价与现场验证差异","why":"合成标签与训练样本来自同一生成机制，预测差值和高评分均不构成真实提效证据。"}]},"demo":{"mode":"page","html":"demo/index.html","js":"demo/demo.js","height":1000,"label":"案例演示","intro":"固定种子生成虚拟井，按井训练并测试多项式岭回归；调整流量、岩层与参数上限，观察预测热力图、当前与推荐对比、独立测试散点及 MAE/R²，点击应用推荐更新演示参数。全部数据为教学合成，不连接现场设备。"}}},"files":[{"name":"demo/demo.css","size":6402,"enc":"text","data":":root{--paper:#fbfaf6;--card:#fff;--ink:#242b2e;--muted:#56646b;--line:#ddd7c8;--jade:#2f7d6b;--jade-light:#e6f1ec;--blue:#41699b;--blue-light:#e7eef9;--warn:#8e5229;--warn-light:#f8ecdf;--bad:#a34138;font-family:-apple-system,BlinkMacSystemFont,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;color:var(--ink);background:var(--paper);font-size:14px;line-height:1.7}\n*{box-sizing:border-box}body{margin:0}main{max-width:1280px;margin:auto;padding:24px}h1,h2,h3,p{margin:0}h1{font-size:clamp(22px,3vw,30px);line-height:1.35;letter-spacing:-.5px;font-weight:650}h2{font-size:17px;line-height:1.5}h3{font-size:14px;margin-bottom:8px}p{color:var(--muted)}button,input,select{font:inherit}button,select{min-height:42px}button{border:1px solid var(--jade);background:var(--jade);color:white;padding:8px 16px;border-radius:6px;cursor:pointer;font-weight:600}button:hover{filter:brightness(.94)}button:disabled{opacity:.55;cursor:default}button.quiet{background:transparent;color:var(--jade);border-color:var(--line);font-weight:500}button:focus-visible,select:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid var(--blue);outline-offset:4px}.intro{display:flex;align-items:flex-start;justify-content:space-between;gap:20px;margin-bottom:24px}.intro p{max-width:650px;margin-top:10px}.source{white-space:nowrap;background:var(--jade-light);color:#235f51;padding:5px 10px;border-radius:4px;font-size:12px}.experiment{display:grid;grid-template-columns:260px minmax(0,1fr);background:white;border:1px solid var(--line);border-radius:10px;overflow:hidden}.controls{background:#f5f6f2;padding:22px;border-right:1px solid var(--line)}.controls h2{margin-bottom:16px}.field{display:block;font-weight:600}.field select{display:block;width:100%;background:white;border:1px solid #b5bdb8;border-radius:5px;margin:8px 0 7px;padding:7px;color:var(--ink)}.hint{font-size:12px;color:var(--muted);line-height:1.7}.slider{margin-top:20px}.slider label{display:flex;justify-content:space-between;gap:5px;font-size:13px}.slider label span{font-variant-numeric:tabular-nums;color:var(--jade);font-weight:600}.slider input{display:block;width:100%;accent-color:var(--jade);margin:10px 0 6px;cursor:pointer}.slider small{display:block;font-size:11px;color:var(--muted)}fieldset{margin:22px 0 17px;padding:0;border:0;border-top:1px solid var(--line)}legend{font-size:12px;color:var(--muted);padding-right:8px}fieldset .slider{margin:12px 0}fieldset .slider label span{color:var(--blue)}fieldset input{accent-color:var(--blue)}.landscape{padding:22px;min-width:0}.section-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.section-heading p{font-size:12px;margin-top:4px}.unit{font-size:11px;color:var(--muted);white-space:nowrap}svg{display:block;width:100%;height:auto;overflow:visible}svg text{font-family:inherit;font-size:12px;fill:var(--muted)}#heatmap{margin-top:14px}.legend{display:flex;gap:18px;flex-wrap:wrap;font-size:12px;color:var(--muted);margin:0 0 12px 14px}.legend span{display:flex;align-items:center;gap:7px}.legend i{display:inline-block;width:12px;height:12px}.current-dot{border:2px solid #242b2e;border-radius:50%;background:white}.best-dot{background:var(--blue);transform:rotate(45deg);border:1px solid white}.mask-dot{background:repeating-linear-gradient(135deg,#aeb6b8 0px,#aeb6b8 1px,#edf0ef 1px,#edf0ef 4px)}.explanation{font-size:12px;min-height:42px;padding:10px 12px;background:#f3f6f6;border-left:3px solid #93b4a6}.result{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));padding:18px 0;margin-top:5px;gap:16px;border-bottom:1px solid var(--line)}.result>div{font-variant-numeric:tabular-nums}.result span{display:block;font-size:12px;color:var(--muted)}.result strong{font-size:30px;line-height:1.6;font-weight:600;letter-spacing:-1px}.result small{margin-left:5px;font-size:12px;color:var(--muted)}.result>div:nth-child(2) strong{color:var(--jade)}.recommendation{display:flex;gap:14px;justify-content:space-between;align-items:center;margin-top:16px}.recommendation p{font-size:13px}.recommendation button{flex-shrink:0}.status{margin-top:10px;font-size:12px;color:var(--jade);min-height:20px}.status.outside{color:var(--bad)}.interpretation{display:grid;grid-template-columns:1fr 1fr;gap:28px;margin-top:28px}.interpretation article{min-width:0}.interpretation h2{margin-bottom:9px}.interpretation p{font-size:13px}.interpretation svg{margin:10px 0}.metrics{display:flex;flex-wrap:wrap;gap:6px 18px;padding:10px 0;border-top:1px solid var(--line);font-size:12px}.metrics b{color:var(--jade);font-size:16px;font-variant-numeric:tabular-nums}.interpretation .hint{font-size:12px}details{border-top:1px solid var(--line);padding-top:12px;margin-top:15px}summary{cursor:pointer;font-weight:600;font-size:13px}details p{margin-top:10px}.model-notes{margin-top:28px}.split{display:flex;gap:3px;margin:18px 0 20px}.split span{background:var(--jade-light);color:#235f51;padding:9px 10px;font-size:12px;flex:4}.split span:nth-child(2){background:var(--blue-light);color:#37587f;flex:1}.split span:nth-child(3){background:var(--warn-light);color:var(--warn);flex:1}.model-grid{display:grid;grid-template-columns:1fr 1fr;gap:28px}.model-grid p{font-size:12px}.lambda-results{display:flex;flex-wrap:wrap;gap:8px;margin:18px 0}.lambda-option{background:white;border:1px solid var(--line);padding:7px 10px;font-size:12px}.lambda-option.selected{border-color:var(--jade);background:var(--jade-light);color:#235f51}.lambda-option b{margin-left:6px}footer{font-size:12px;color:var(--muted);border-top:1px solid var(--line);margin-top:24px;padding-top:16px;max-width:950px}\n@media(min-width:1100px){.landscape{padding:26px 30px}#heatmap{max-width:750px;margin-left:auto;margin-right:auto}}\n@media(max-width:760px){main{padding:14px}.intro{display:block}.source{display:inline-block;margin-top:12px}.experiment{grid-template-columns:1fr}.controls{border-right:0;border-bottom:1px solid var(--line);padding:18px}.controls .slider{margin-top:14px}.landscape{padding:16px}.interpretation{grid-template-columns:1fr;gap:24px}.model-grid{grid-template-columns:1fr;gap:18px}.recommendation{flex-wrap:wrap}.result strong{font-size:25px}.split{flex-wrap:wrap}.split span{flex:1!important;min-width:110px}.unit{display:none}.legend{gap:12px;margin-left:0}.section-heading{display:block}}\n@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}\n"},{"name":"demo/demo.js","size":15540,"enc":"text","data":"/* 教学实验：固定种子合成样本 → 按井切分 → 多项式岭回归 → 约束网格搜索。\n   无网络、无第三方依赖。生成规则只用于造样本，不参与参数推荐。 */\n(function (global) {\n  'use strict';\n  var ROCKS = ['砂岩', '页岩', '致密灰岩'];\n  var LAMBDAS = [0.01, 0.1, 1, 10, 100];\n  function random(seed) {\n    return function () {\n      seed |= 0; seed = (seed + 0x6D2B79F5) | 0;\n      var t = Math.imul(seed ^ (seed >>> 15), 1 | seed);\n      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;\n      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;\n    };\n  }\n  function generate(seed) {\n    var rand = random(seed), rows = [];\n    function normal() { return Math.sqrt(-2 * Math.log(Math.max(rand(), 1e-12))) * Math.cos(2 * Math.PI * rand()); }\n    for (var well = 0; well < 18; well++) {\n      var wellOffset = normal() * 0.8;\n      for (var j = 0; j < 60; j++) {\n        var rock = j % 3, wob = 40 + rand() * 120, rpm = 60 + rand() * 160, flow = 18 + rand() * 20;\n        var w = (wob - 100) / 60, r = (rpm - 140) / 80, q = (flow - 28) / 10;\n        // 人为构造的非线性响应，不是经验钻速公式，也不是工程标定结果。\n        var expected = [38, 29, 23][rock] + (13 - rock * 2) * w + (9 - rock) * r + 3 * q\n          - 11 * w * w - 8 * r * r - 2 * q * q + 2 * w * r + w * q - r * q;\n        var rop = Math.max(0.5, expected + wellOffset + normal() * (1.3 + rock * 0.3));\n        rows.push({ well: well + 1, rock: rock, wob: wob, rpm: rpm, flow: flow, rop: rop,\n          split: well < 12 ? 'train' : well < 15 ? 'validation' : 'test' });\n      }\n    }\n    return rows;\n  }\n  function features(row) {\n    var w = (row.wob - 100) / 60, r = (row.rpm - 140) / 80, q = (row.flow - 28) / 10;\n    var a = row.rock === 1 ? 1 : 0, b = row.rock === 2 ? 1 : 0;\n    return [w, r, q, w * w, r * r, q * q, w * r, w * q, r * q, a, b, a * w, b * w, a * r, b * r, a * q, b * q];\n  }\n  function solve(matrix, rhs) {\n    var a = matrix.map(function (row, i) { return row.concat(rhs[i]); }), n = rhs.length;\n    for (var col = 0; col < n; col++) {\n      var pivot = col;\n      for (var k = col + 1; k < n; k++) if (Math.abs(a[k][col]) > Math.abs(a[pivot][col])) pivot = k;\n      if (Math.abs(a[pivot][col]) < 1e-12) throw new Error('模型求解失败：矩阵接近奇异。');\n      var temp = a[col]; a[col] = a[pivot]; a[pivot] = temp;\n      var div = a[col][col];\n      for (var j = col; j <= n; j++) a[col][j] /= div;\n      for (var i = 0; i < n; i++) {\n        if (i === col) continue;\n        var f = a[i][col];\n        for (var j2 = col; j2 <= n; j2++) a[i][j2] -= f * a[col][j2];\n      }\n    }\n    return a.map(function (row) { return row[n]; });\n  }\n  function fit(rows, lambda) {\n    var raw = rows.map(features), p = raw[0].length, n = rows.length;\n    var mean = Array(p).fill(0), scale = Array(p).fill(0);\n    raw.forEach(function (x) { x.forEach(function (v, j) { mean[j] += v / n; }); });\n    raw.forEach(function (x) { x.forEach(function (v, j) { scale[j] += Math.pow(v - mean[j], 2) / n; }); });\n    scale = scale.map(function (v) { return Math.sqrt(v) || 1; });\n    var xtx = Array.from({ length: p + 1 }, function () { return Array(p + 1).fill(0); }), xty = Array(p + 1).fill(0);\n    raw.forEach(function (x, i) {\n      var z = [1].concat(x.map(function (v, j) { return (v - mean[j]) / scale[j]; }));\n      for (var a = 0; a <= p; a++) {\n        xty[a] += z[a] * rows[i].rop;\n        for (var b = 0; b <= p; b++) xtx[a][b] += z[a] * z[b];\n      }\n    });\n    // 目标：Σ(y-Xβ)² + λΣβ²，截距不惩罚。\n    for (var d = 1; d <= p; d++) xtx[d][d] += lambda;\n    var beta = solve(xtx, xty);\n    return { lambda: lambda, mean: mean, scale: scale, beta: beta, predict: function (row) {\n      // 与合成观测采用同一教学下限，避免线性输出出现负钻速。\n      return Math.max(0.5, features(row).reduce(function (sum, v, j) { return sum + beta[j + 1] * (v - mean[j]) / scale[j]; }, beta[0]));\n    } };\n  }\n  function evaluate(model, rows) {\n    var avg = rows.reduce(function (s, r) { return s + r.rop; }, 0) / rows.length, ae = 0, sse = 0, sst = 0;\n    rows.forEach(function (row) { var err = model.predict(row) - row.rop; ae += Math.abs(err); sse += err * err; sst += Math.pow(row.rop - avg, 2); });\n    return { mae: ae / rows.length, r2: sst ? 1 - sse / sst : null };\n  }\n  function train(rows) {\n    var training = rows.filter(function (r) { return r.split === 'train'; });\n    var validation = rows.filter(function (r) { return r.split === 'validation'; });\n    var testing = rows.filter(function (r) { return r.split === 'test'; });\n    var candidates = LAMBDAS.map(function (lambda) { var model = fit(training, lambda); return { model: model, score: evaluate(model, validation) }; });\n    var chosen = candidates.reduce(function (a, b) { return a.score.mae < b.score.mae ? a : b; });\n    var avg = training.reduce(function (s, r) { return s + r.rop; }, 0) / training.length;\n    return { model: chosen.model, candidates: candidates, test: testing, score: evaluate(chosen.model, testing),\n      baseline: evaluate({ predict: function () { return avg; } }, testing) };\n  }\n  function optimize(model, state) {\n    var best = null, grid = [], feasible = 0;\n    for (var rpm = 60; rpm <= 220; rpm += 4) {\n      for (var wob = 40; wob <= 160; wob += 4) {\n        var point = { wob: wob, rpm: rpm, flow: state.flow, rock: state.rock };\n        point.value = model.predict(point);\n        point.feasible = wob <= state.maxWob && rpm <= state.maxRpm;\n        grid.push(point);\n        if (point.feasible) { feasible++; if (!best || point.value > best.value) best = point; }\n      }\n    }\n    return { best: best, grid: grid, feasible: feasible };\n  }\n  var API = { generate: generate, fit: fit, train: train, evaluate: evaluate, optimize: optimize, features: features };\n  global.DrillingROP = API;\n  if (typeof module !== 'undefined' && module.exports) module.exports = API;\n  if (typeof document === 'undefined') return;\n\n  var rows = generate(20261023), learned = train(rows), model = learned.model;\n  var ids = ['rock', 'wob', 'rpm', 'flow', 'max-wob', 'max-rpm'];\n  var state, search, applied = false;\n  function byId(id) { return document.getElementById(id); }\n  function fmt(v, n) { return v === null ? '不可定义' : v.toFixed(n === undefined ? 1 : n); }\n  function text(id, value) { byId(id).textContent = value; }\n  function readState() { return { rock: +byId('rock').value, wob: +byId('wob').value, rpm: +byId('rpm').value, flow: +byId('flow').value, maxWob: +byId('max-wob').value, maxRpm: +byId('max-rpm').value }; }\n  function line(x1, y1, x2, y2, extra) { return '<line x1=\"' + x1 + '\" y1=\"' + y1 + '\" x2=\"' + x2 + '\" y2=\"' + y2 + '\" ' + (extra || '') + '/>'; }\n  function label(x, y, value, extra) { return '<text x=\"' + x + '\" y=\"' + y + '\" ' + (extra || '') + '>' + value + '</text>'; }\n  function color(t) { t = Math.max(0, Math.min(1, t)); var low = [235, 245, 237], high = [36, 112, 100]; return 'rgb(' + low.map(function (c, j) { return Math.round(c + (high[j] - c) * t); }).join(',') + ')'; }\n  function drawHeatmap() {\n    var x0 = 64, y0 = 25, width = 560, height = 328, cw = width / 31, ch = height / 41;\n    function x(w) { return x0 + ((w - 40) / 4 + 0.5) * cw; }\n    function y(r) { return y0 + ((220 - r) / 4 + 0.5) * ch; }\n    var s = '<title id=\"heat-title\">参数组合与预测机械钻速热力图</title><desc id=\"heat-desc\">' + ROCKS[state.rock] + '，排量 ' + state.flow + ' L/s。灰色斜线区超出操作上限，圆圈是当前参数，菱形是推荐参数。</desc>';\n    s += '<defs><pattern id=\"excluded\" width=\"7\" height=\"7\" patternUnits=\"userSpaceOnUse\"><rect width=\"7\" height=\"7\" fill=\"#edf0ef\"/><path d=\"M-1 1L1-1M0 7L7 0M6 8L8 6\" stroke=\"#b5bdbb\" stroke-width=\"1\"/></pattern><linearGradient id=\"ramp\">';\n    for (var c = 0; c <= 4; c++) s += '<stop offset=\"' + c * 25 + '%\" stop-color=\"' + color(c / 4) + '\"/>';\n    s += '</linearGradient></defs>';\n    search.grid.forEach(function (p) { s += '<rect x=\"' + (x(p.wob) - cw / 2) + '\" y=\"' + (y(p.rpm) - ch / 2) + '\" width=\"' + (cw + 0.15) + '\" height=\"' + (ch + 0.15) + '\" fill=\"' + (p.feasible ? color(p.value / 50) : 'url(#excluded)') + '\"><title>钻压 ' + p.wob + ' kN，转速 ' + p.rpm + ' r/min：' + fmt(p.value) + ' m/h' + (p.feasible ? '' : '，超出操作上限') + '</title></rect>'; });\n    s += '<rect x=\"' + x0 + '\" y=\"' + y0 + '\" width=\"' + width + '\" height=\"' + height + '\" fill=\"none\" stroke=\"#b5bdbb\"/>';\n    [40, 60, 80, 100, 120, 140, 160].forEach(function (v) { s += label(x(v), y0 + height + 21, v, 'text-anchor=\"middle\"'); });\n    [60, 100, 140, 180, 220].forEach(function (v) { s += label(x0 - 12, y(v) + 4, v, 'text-anchor=\"end\"'); });\n    s += label(x0 + width / 2, y0 + height + 47, '钻压 kN', 'text-anchor=\"middle\"');\n    s += '<text transform=\"translate(19 ' + (y0 + height / 2) + ') rotate(-90)\" text-anchor=\"middle\">转速 r/min</text>';\n    s += '<rect x=\"' + (x0 + width - 150) + '\" y=\"' + (y0 + height + 62) + '\" width=\"150\" height=\"8\" fill=\"url(#ramp)\"/>';\n    s += label(x0 + width - 150, y0 + height + 84, '0') + label(x0 + width, y0 + height + 84, '50 m/h', 'text-anchor=\"end\"');\n    var b = search.best, bx = x(b.wob), by = y(b.rpm);\n    s += '<path d=\"M' + bx + ' ' + (by - 9) + 'l9 9-9 9-9-9z\" fill=\"#41699b\" stroke=\"white\" stroke-width=\"2\"/>';\n    s += '<circle cx=\"' + x(state.wob) + '\" cy=\"' + y(state.rpm) + '\" r=\"7\" fill=\"white\" stroke=\"#242b2e\" stroke-width=\"2.5\"/>';\n    if (state.wob === b.wob && state.rpm === b.rpm) s += '<circle cx=\"' + bx + '\" cy=\"' + by + '\" r=\"3\" fill=\"#41699b\"/>';\n    byId('heatmap').innerHTML = s;\n  }\n  function drawResponse() {\n    var w = 510, h = 280, left = 55, top = 20, right = 20, bottom = 48;\n    function x(v) { return left + (v - 40) / 120 * (w - left - right); }\n    function y(v) { return h - bottom - v / 60 * (h - bottom - top); }\n    var s = '';\n    [0, 20, 40, 60].forEach(function (v) { s += line(left, y(v), w - right, y(v), 'stroke=\"#e1e7e3\"') + label(left - 8, y(v) + 4, v, 'text-anchor=\"end\"'); });\n    [40, 80, 120, 160].forEach(function (v) { s += label(x(v), h - bottom + 20, v, 'text-anchor=\"middle\"'); });\n    var path = '';\n    for (var wob = 40; wob <= 160; wob += 2) path += (wob === 40 ? 'M' : 'L') + x(wob) + ',' + y(model.predict({ wob: wob, rpm: state.rpm, flow: state.flow, rock: state.rock }));\n    s += '<path d=\"' + path + '\" fill=\"none\" stroke=\"#2f7d6b\" stroke-width=\"3\"/>';\n    s += line(x(state.maxWob), top, x(state.maxWob), h - bottom, 'stroke=\"#41699b\" stroke-dasharray=\"5 4\"');\n    s += label(x(state.maxWob) - 5, top + 12, '钻压上限', 'text-anchor=\"end\"');\n    s += '<circle cx=\"' + x(state.wob) + '\" cy=\"' + y(model.predict(state)) + '\" r=\"5\" fill=\"white\" stroke=\"#242b2e\" stroke-width=\"2\"/>';\n    s += label(left, 12, '预测钻速 m/h') + label(w / 2, h - 5, '钻压 kN', 'text-anchor=\"middle\"');\n    byId('response').innerHTML = s;\n  }\n  function drawScatter() {\n    var left = 55, top = 24, right = 485, bottom = 232, max = 60;\n    function x(v) { return left + v / max * (right - left); }\n    function y(v) { return bottom - v / max * (bottom - top); }\n    var s = '';\n    [0, 20, 40, 60].forEach(function (v) { s += line(left, y(v), right, y(v), 'stroke=\"#e1e7e3\"') + label(left - 8, y(v) + 4, v, 'text-anchor=\"end\"') + label(x(v), bottom + 21, v, 'text-anchor=\"middle\"'); });\n    s += line(x(0), y(0), x(max), y(max), 'stroke=\"#8e9994\" stroke-dasharray=\"5 4\"');\n    learned.test.forEach(function (p) { s += '<circle cx=\"' + x(p.rop) + '\" cy=\"' + y(model.predict(p)) + '\" r=\"3\" fill=\"' + ['#2f7d6b', '#41699b', '#b26a39'][p.rock] + '\" opacity=\".6\"><title>' + ROCKS[p.rock] + ' · 虚拟井 ' + p.well + '：观测 ' + fmt(p.rop) + '，预测 ' + fmt(model.predict(p)) + ' m/h</title></circle>'; });\n    s += label(left, 14, '模型预测 m/h') + label(270, 276, '合成观测钻速 m/h', 'text-anchor=\"middle\"');\n    byId('scatter').innerHTML = s;\n    text('mae', fmt(learned.score.mae, 2)); text('r2', fmt(learned.score.r2, 3)); text('baseline', fmt(learned.baseline.mae, 2));\n    text('model-choice', '验证集从 5 个候选正则化强度中选择 λ = ' + model.lambda + '；选定后保持训练模型不变，最后才评价 3 口测试井。');\n    byId('lambda-results').innerHTML = learned.candidates.map(function (c) { return '<span class=\"lambda-option' + (c.model.lambda === model.lambda ? ' selected' : '') + '\">λ ' + c.model.lambda + '：<b>' + fmt(c.score.mae, 3) + '</b> m/h' + (c.model.lambda === model.lambda ? ' · 选中' : '') + '</span>'; }).join('');\n  }\n  function render() {\n    state = readState(); search = optimize(model, state);\n    ids.slice(1).forEach(function (id) { text(id + '-value', byId(id).value); });\n    var current = model.predict(state), best = search.best;\n    var feasible = state.wob <= state.maxWob && state.rpm <= state.maxRpm;\n    var gain = (best.value / current - 1) * 100;\n    text('current-rop', fmt(current)); text('best-rop', fmt(best.value));\n    text('gain', (gain >= 0 ? '+' : '') + fmt(gain));\n    text('gain-label', feasible ? '预测变化' : '约束调整后变化');\n    text('recommend-text', ROCKS[state.rock] + '，排量 ' + state.flow + ' L/s：推荐钻压 ' + best.wob + ' kN、转速 ' + best.rpm + ' r/min。');\n    text('map-summary', '当前有 ' + search.feasible + ' / ' + search.grid.length + ' 组参数满足上限。' + (feasible ? '调低操作上限，观察推荐点如何移动；切换岩层，观察整个响应面如何变化。' : '当前设置已经超出操作上限；推荐结果可能比当前更慢，因为先满足约束再追求钻速。'));\n    text('status', !feasible ? '当前设置超出本次操作上限，请应用推荐参数或调整当前设置。' : applied ? '已应用推荐参数。继续改变岩层或操作上限，观察推荐如何变化。' : '比较的是模型预测值，预测变化不是实测提速收益。');\n    byId('status').className = 'status' + (!feasible ? ' outside' : '');\n    byId('apply').disabled = state.wob === best.wob && state.rpm === best.rpm;\n    text('time-story', '假设连续钻进 100 m：当前预测需要 ' + fmt(100 / current) + ' h，推荐预测需要 ' + fmt(100 / best.value) + ' h。该时间只由进尺 ÷ 预测机械钻速计算，不是整段作业工期。');\n    drawHeatmap(); drawResponse();\n  }\n  ids.forEach(function (id) { byId(id).addEventListener(id === 'rock' ? 'change' : 'input', function () { applied = false; render(); }); });\n  byId('apply').addEventListener('click', function () { byId('wob').value = search.best.wob; byId('rpm').value = search.best.rpm; applied = true; render(); });\n  byId('reset').addEventListener('click', function () {\n    var defaults = [0, 84, 108, 28, 140, 180]; ids.forEach(function (id, i) { byId(id).value = defaults[i]; }); applied = false; render();\n  });\n  byId('download').addEventListener('click', function () {\n    var csv = '\\uFEFFwell_id,split,rock,wob_kN,rpm,flow_L_s,rop_m_h\\n' + rows.map(function (r) { return [r.well, r.split, ROCKS[r.rock], fmt(r.wob, 3), fmt(r.rpm, 3), fmt(r.flow, 3), fmt(r.rop, 3)].join(','); }).join('\\n');\n    var url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' })), a = document.createElement('a');\n    a.href = url; a.download = 'drilling-rop-synthetic.csv'; a.click(); setTimeout(function () { URL.revokeObjectURL(url); }, 1000);\n  });\n  drawScatter(); render();\n})(typeof window !== 'undefined' ? window : globalThis);\n"},{"name":"demo/index.html","size":7343,"enc":"text","data":"<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>钻速预测与参数优化 · 交互实验</title>\n  <link rel=\"stylesheet\" href=\"demo.css\">\n</head>\n<body>\n<main>\n  <header class=\"intro\">\n    <div>\n      <h1>钻速预测与参数优化</h1>\n      <p>先用历史样本学习参数与机械钻速的关系，再在给定约束内寻找更好的参数组合。</p>\n    </div>\n    <span class=\"source\">教学合成数据 · 本地计算</span>\n  </header>\n\n  <section class=\"experiment\" aria-label=\"钻井参数实验\">\n    <aside class=\"controls\">\n      <h2>当前钻井工况</h2>\n      <label class=\"field\" for=\"rock\">当前钻遇岩层\n        <select id=\"rock\"><option value=\"0\">砂岩 · 较易钻进</option><option value=\"1\">页岩 · 中等可钻性</option><option value=\"2\">致密灰岩 · 较难钻进</option></select>\n      </label>\n      <p class=\"hint\">软硬排序仅用于本例；实际可钻性还受胶结、强度、钻头等影响。</p>\n      <div class=\"slider\"><label for=\"wob\">钻压 <span><output id=\"wob-value\" for=\"wob\">84</output> kN</span></label><input id=\"wob\" type=\"range\" min=\"40\" max=\"160\" step=\"4\" value=\"84\"><small>钻头向下压在岩石上的力</small></div>\n      <div class=\"slider\"><label for=\"rpm\">转速 <span><output id=\"rpm-value\" for=\"rpm\">108</output> r/min</span></label><input id=\"rpm\" type=\"range\" min=\"60\" max=\"220\" step=\"4\" value=\"108\"><small>钻头每分钟旋转的圈数</small></div>\n      <div class=\"slider\"><label for=\"flow\">排量 <span><output id=\"flow-value\" for=\"flow\">28</output> L/s</span></label><input id=\"flow\" type=\"range\" min=\"18\" max=\"38\" step=\"1\" value=\"28\"><small>钻井液的循环流量，影响井底清洁</small></div>\n      <fieldset>\n        <legend>本次搜索的操作上限</legend>\n        <div class=\"slider\"><label for=\"max-wob\">钻压上限 <span><output id=\"max-wob-value\" for=\"max-wob\">140</output> kN</span></label><input id=\"max-wob\" type=\"range\" min=\"40\" max=\"160\" step=\"4\" value=\"140\"></div>\n        <div class=\"slider\"><label for=\"max-rpm\">转速上限 <span><output id=\"max-rpm-value\" for=\"max-rpm\">180</output> r/min</span></label><input id=\"max-rpm\" type=\"range\" min=\"60\" max=\"220\" step=\"4\" value=\"180\"></div>\n        <p class=\"hint\">上限是教学约束，不代表现场安全限值。</p>\n      </fieldset>\n      <button id=\"reset\" type=\"button\" class=\"quiet\">恢复初始工况</button>\n    </aside>\n\n    <div class=\"landscape\">\n      <div class=\"section-heading\"><div><h2>钻速预测与参数推荐</h2><p>固定岩层与排量，比较 1,271 组钻压 / 转速组合。</p></div><span class=\"unit\">预测钻速 m/h</span></div>\n      <svg id=\"heatmap\" viewBox=\"0 0 690 440\" role=\"img\" aria-labelledby=\"heat-title heat-desc\"><title id=\"heat-title\">参数组合与预测机械钻速热力图</title><desc id=\"heat-desc\">横轴为钻压，纵轴为转速。颜色越深预测钻速越高，灰色斜线区超出操作上限。圆圈为当前参数，菱形为推荐参数。</desc></svg>\n      <div class=\"legend\"><span><i class=\"current-dot\"></i>当前设置</span><span><i class=\"best-dot\"></i>约束内推荐</span><span><i class=\"mask-dot\"></i>超出上限</span></div>\n      <p id=\"map-summary\" class=\"explanation\"></p>\n      <div class=\"result\" aria-live=\"polite\" aria-atomic=\"true\">\n        <div><span>当前预测</span><strong id=\"current-rop\">—</strong><small>m/h</small></div>\n        <div><span>推荐预测</span><strong id=\"best-rop\">—</strong><small>m/h</small></div>\n        <div><span id=\"gain-label\">预测变化</span><strong id=\"gain\">—</strong><small id=\"gain-unit\">%</small></div>\n      </div>\n      <div class=\"recommendation\"><p id=\"recommend-text\"></p><button id=\"apply\" type=\"button\">应用推荐参数</button></div>\n      <p id=\"status\" class=\"status\" role=\"status\"></p>\n    </div>\n  </section>\n\n  <section class=\"interpretation\" aria-label=\"解释参数与验证模型\">\n    <article class=\"mechanics\">\n      <h2>钻压与钻速响应曲线</h2>\n      <p>更大的钻压帮助钻头压入岩石，更高的转速增加切削次数；但收益不会无限增加。本例让模型从样本中学习这种弯曲的响应关系。</p>\n      <svg id=\"response\" viewBox=\"0 0 510 280\" role=\"img\" aria-label=\"固定当前转速和排量时，钻压与预测钻速的关系\"></svg>\n      <p class=\"hint\">曲线固定当前转速、排量及岩层；圆点对应当前钻压。推荐方案同时搜索钻压和转速，因此不一定落在这条曲线上。</p>\n      <details><summary>机械钻速与钻进时间换算</summary><p id=\"time-story\"></p><p>机械钻速只统计钻头实际破岩时的进尺速度；接单根、起下钻等非钻进时间没有计入。</p></details>\n    </article>\n    <article class=\"validation\">\n      <div class=\"section-heading\"><div><h2>独立测试井预测误差</h2><p>测试集只评价，不用于挑选模型或参数。</p></div></div>\n      <svg id=\"scatter\" viewBox=\"0 0 510 280\" role=\"img\" aria-label=\"独立测试井上，合成观测钻速与模型预测钻速的对比散点图\"></svg>\n      <div class=\"legend rock-legend\"><span><i style=\"background:#2f7d6b\"></i>砂岩</span><span><i style=\"background:#41699b\"></i>页岩</span><span><i style=\"background:#b26a39\"></i>致密灰岩</span></div>\n      <div class=\"metrics\"><span>测试 MAE <b id=\"mae\">—</b> m/h</span><span>测试 R² <b id=\"r2\">—</b></span><span>均值基线 MAE <b id=\"baseline\">—</b> m/h</span></div>\n      <p class=\"hint\">点越靠近对角线，预测越接近合成观测值。MAE 是平均绝对误差；R² 衡量相对均值预测的拟合程度，可为负数。</p>\n    </article>\n  </section>\n\n  <details class=\"model-notes\" open>\n    <summary>模型训练与参数搜索方法</summary>\n    <div class=\"split\" aria-label=\"按井划分数据：12口训练井720条，3口验证井180条，3口测试井180条\"><span>训练 · 12 井 / 720 条</span><span>验证 · 3 井 / 180 条</span><span>测试 · 3 井 / 180 条</span></div>\n    <div class=\"model-grid\">\n      <div><h3>多项式岭回归训练</h3><p>固定随机种子生成 18 口虚拟井。用钻压、转速、排量的二次项与交互项，以及岩层类别训练岭回归。特征的均值与标准差只从训练井计算。合成观测与模型预测均采用 0.5 m/h 的教学下限，避免出现负钻速。</p><p id=\"model-choice\"></p></div>\n      <div><h3>约束参数网格搜索</h3><p>每次调整控件，都由训练好的模型重新预测参数网格。去掉超出上限的组合后，选预测钻速最高的一组。搜索步长：钻压 4 kN、转速 4 r/min；排量保持当前值。</p><p>本例为表格回归与网格寻优，没有使用时序网络或强化学习。</p></div>\n    </div>\n    <div id=\"lambda-results\" class=\"lambda-results\" aria-label=\"不同正则化强度的验证误差\"></div>\n    <button id=\"download\" type=\"button\" class=\"quiet\">导出合成样本 CSV</button>\n  </details>\n  <footer>这是智能化方法的教学实验。合成样本中的相关性由生成规则设定，不能证明真实井上的提速收益；现场还需验证钻头、扭矩、泵压、振动与井壁稳定等条件。</footer>\n</main>\n<script src=\"demo.js\"></script>\n</body>\n</html>\n"}]};
  // Local uploads take precedence. Keep the original importer and its package contract.
  var sc = global.ATLAS.index.byScene[pack.manifest.sceneId];
  var existing = global.Cases.get(pack.manifest.id);
  if (existing) {
    if (sc && existing.tabs && existing.tabs.demo) sc.demo = true;
    return;
  }
  if (global.CaseImport.blockedList().indexOf(pack.manifest.id) >= 0) return;
  var c = pack.manifest;
  var cfg = c.tabs.demo;
  var handle = null;
  c.status = 'ready';
  c.tabs.demo = {
    label: cfg.label, intro: cfg.intro,
    mount: function (root, ctx) {
      handle = global.CaseDemoHost.create(root, { files: pack.files, demo: cfg, meta: c }, ctx);
    },
    unmount: function () { if (handle) { handle.destroy(); handle = null; } }
  };
  global.Cases.register(c);
  if (sc) sc.demo = true;
})(window);
